import{_ as i,a0 as p,w as l,s as d,ao as r,I as o,x as a,a1 as e,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const U=JSON.parse('{"title":"如何在局域網中將Ubuntu文件夾共享給Windows | LCTT x X-CMD","titleTemplate":false,"description":"如何在局域網中將Ubuntu文件夾共享給Windows | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在局域網中將Ubuntu文件夾共享給Windows | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在局域網中將Ubuntu文件夾共享給Windows | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150304 Share Folders On Local Network Between Ubuntu And Windows","title":"如何在局域網中將Ubuntu文件夾共享給Windows","tag":"201505","desc":""},"relativePath":"201505/20150304 Share Folders On Local Network Between Ubuntu And Windows.md","filePath":"[post].md"}'),u={name:"201505/20150304 Share Folders On Local Network Between Ubuntu And Windows.md"};function m(b,t,h,c,g,f){const s=p("Link");return l(),d("div",null,[t[16]||(t[16]=r(`<h1 id="如何在局域網中將ubuntu文件夾共享給windows" tabindex="-1">如何在局域網中將Ubuntu文件夾共享給Windows <a class="header-anchor" href="#如何在局域網中將ubuntu文件夾共享給windows" aria-label="Permalink to “如何在局域網中將Ubuntu文件夾共享給Windows”">​</a></h1><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/03/Share_Folder_Ubuntu_windows.jpeg" alt=""></p><p>本文全面詳細地向你描述了<strong>在Ubuntu中如何實現局域網內的文件夾共享</strong>。</p><p>你的家中是不是有多台電腦？當你需要從一台Ubuntu電腦向另一台電腦傳輸數據時，是不是必須用到U盤或SD卡？你是否也覺得這個方法很煩人？我想肯定是。本文的目的就是使你在局域網內快速方便地傳輸文件、文檔和其它較大的數據，以節省你的寶貴時間。只需一次設置，然後輕點鼠標，你就可以自由地<strong>在Ubuntu和Windows之間共享文件</strong>，當然這對其它Linux系統同樣使用。不要擔心，這很容易操作，不會花費太多時間。</p><p>除此之外，儘管本文是在Ubuntu上進行實踐，但這個教程在其它Linux系統上同樣有用。</p><h4 id="在ubuntu上實現局域網共享文件夾" tabindex="-1">在Ubuntu上實現局域網共享文件夾 <a class="header-anchor" href="#在ubuntu上實現局域網共享文件夾" aria-label="Permalink to “在Ubuntu上實現局域網共享文件夾”">​</a></h4><p>如果你的系統是Ubuntu 14.04、14.10或12.04，有兩個方法可以使你通過局域網在搭載Windows或其他Linux的電腦上共享本地文件。</p><ul><li>對局域網中的每個用户提供無密碼共享</li><li>僅限特定訪問，提供文件夾密碼保護</li></ul><p>這篇文章包括兩種方法，你可以選擇你想用的那種。</p><h3 id="_1-局域網無密碼共享文件夾" tabindex="-1">1. 局域網無密碼共享文件夾 <a class="header-anchor" href="#_1-局域網無密碼共享文件夾" aria-label="Permalink to “1. 局域網無密碼共享文件夾”">​</a></h3><h4 id="步驟一" tabindex="-1">步驟一：#### <a class="header-anchor" href="#步驟一" aria-label="Permalink to “步驟一：####”">​</a></h4><p>為了在Ubuntu上實現局域網共享文件夾，右鍵點擊打算共享的文件夾，並選擇“Local Network Share（本地網絡共享）”：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/Share_Folder_Ubuntu.jpeg" alt=""></p><p><strong>可能有用的故障解決方案</strong>：如果在右鍵菜單中看不到“Local Network Share”的選項，那就新建一個終端，使用下面的命令去安裝nautlius-share插件：</p><pre><code>sudo apt-get install nautilus-share
</code></pre><p>然後重啓Nautilus。可以選擇註銷再登錄，或者使用這個命令:</p><pre><code>nautilus -q
</code></pre><h4 id="步驟二" tabindex="-1">步驟二：#### <a class="header-anchor" href="#步驟二" aria-label="Permalink to “步驟二：####”">​</a></h4><p>一旦點擊“Local Network Share”，就會出現共享文件夾的選項。只需選中“Share this folder（共享該文件夾）”這一項：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/03/Share_Folder_Ubuntu_1.jpeg" alt=""></p><p><strong>可能的故障解決方案</strong>：如果提示共享服務還未安裝，就像下圖所示，那就點擊安裝服務，按照提示操作。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/03/Share_Folder_Ubuntu_2.jpeg" alt=""></p><h4 id="步驟三" tabindex="-1">步驟三：#### <a class="header-anchor" href="#步驟三" aria-label="Permalink to “步驟三：####”">​</a></h4><p>當選中“Share this folder”的選項，就會看到按鈕“Create Share（創建共享）”變得可以點擊了。你也可以“Allow others to create and delete fies in this folder（允許其他用户在共享文件夾中編輯文件）”。選項“Guest access（允許訪客訪問）”也是如此。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/03/Share_folder_Ubuntu_3.png" alt=""></p><p>你會看到文件夾圖標已經顯示為共享的。如果要停止共享文件夾，只需取消“Share this floder”這個選項。</p><p>這個方法就是這麼簡單，使得局域網中的任何人都可以訪問共享文件夾中的文件。在正常情況下，你會選擇這種方式。因為，家用局域網中的電腦通常都是可信電腦。但情況也不總是這樣。如果你只是想特定的用户才能訪問怎麼辦？這個時候就需要Samba服務器了。我們在本文的第二部分討論這種方法。</p><h3 id="_2-在ubuntu上使用密碼保護實現局域網共享文件夾" tabindex="-1">2. 在Ubuntu上使用密碼保護實現局域網共享文件夾### <a class="header-anchor" href="#_2-在ubuntu上使用密碼保護實現局域網共享文件夾" aria-label="Permalink to “2. 在Ubuntu上使用密碼保護實現局域網共享文件夾###”">​</a></h3>`,28)),o("p",null,[t[1]||(t[1]=a("為了達到這個目的，首先需要配置Samba服務器。事實上，在這篇教程的前一部分我們已經用到了Samba，只是我們沒有刻意強調。在介紹如何在Ubuntu上搭建Samba服務器實現局域網共享的方法之前，先快速預覽一下",-1)),e(s,{href:"http://en.wikipedia.org/wiki/Samba_%28software%29"},{default:n(()=>[...t[0]||(t[0]=[a("Samba",-1)])]),_:1}),t[2]||(t[2]=a("到底是什麼。",-1))]),t[17]||(t[17]=r(`<h4 id="samba是什麼" tabindex="-1">Samba是什麼？ <a class="header-anchor" href="#samba是什麼" aria-label="Permalink to “Samba是什麼？”">​</a></h4><p>Samba是一個允許用户通過網絡共享文件、文檔和打印機的軟件包，無論是在Linux、Windows，還是Mac上。它適用於所有的主流平台，可以在所有支持系統上流暢運行。下面是維基百科的介紹：</p><blockquote><p>Samba是一款重新實現SMB/CIFS網絡協議的自由軟件，最初由安德魯·垂鳩開發。在第三版中，Smaba不僅支持通過不同的Windows客户端訪問及分享SMB的文件夾及打印機，還可以集成到Windows Server域，作為主域控制器（PDC）或者域成員。它也可以作為活動目錄域的一部分。</p></blockquote><h4 id="在ubuntu上安裝samba服務器" tabindex="-1">在Ubuntu上安裝Samba服務器 <a class="header-anchor" href="#在ubuntu上安裝samba服務器" aria-label="Permalink to “在Ubuntu上安裝Samba服務器”">​</a></h4><p>你可以很方便地在Ubuntu電腦上安裝Samba。安裝前，請先更新系統以便安裝任何可用的更新。</p><pre><code>sudo apt-get update &amp;&amp; apt-get upgrade
</code></pre><p>然後按照這條命令安裝samba和少量所需的軟件包：</p><pre><code>sudo apt-get install samba samba-common system-config-samba python-glade2 gksu
</code></pre><p>一旦安裝完成Samba服務器，就可以從圖形界面配置Samba來分享文件。</p><h4 id="在ubuntu上配置samba服務器" tabindex="-1">在Ubuntu上配置Samba服務器 <a class="header-anchor" href="#在ubuntu上配置samba服務器" aria-label="Permalink to “在Ubuntu上配置Samba服務器”">​</a></h4><p>從dash中打開Samba配置工具：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/Setup-Samba.png" alt=""></p><p>進入到<strong>Preference-&gt;Server Settings</strong>。儘管默認已經設置好，可能就是你需要的。但在某些情況下你可能需要做一些改動。</p><p>在Server Setting中可以看到兩個選項卡，‘Basic’和‘Security’。在Basic選項卡下的選項含義如下：</p><ul><li>工作組 - 用户要連接的電腦所在工作組的名字。比如，如果你想連接到一台Windows電腦，你就要輸入Windows電腦的工作組名字。在Windows的Samba服務器設置中，已經默認設置好統一的工作組名字。但如果你有不同的工作組名字，就在這個字段中輸入自定義的工作組名字。（在Windows 7中獲取工作組名字，右擊計算機圖標，進到屬性，就能看到Windows工作組名字。）</li><li>描述 - 其他用户看到的你的電腦名字。不要使用空格或不適用於網絡的字符。</li></ul><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/samba-server-settings.png" alt=""></p><p>設置samba服務器允許‘Guests’可用是不明智的，所以沒必要修改安全設置，保持原樣即可。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/Samba-Security-Settings-compressed.jpg" alt=""></p><p>這就搞定了！你已經搭建好Samba服務器，距離實現網絡共享第一個文件夾的目標不遠了！</p><h4 id="為網絡文件共享創建一個系統用户" tabindex="-1">為網絡文件共享創建一個系統用户 <a class="header-anchor" href="#為網絡文件共享創建一個系統用户" aria-label="Permalink to “為網絡文件共享創建一個系統用户”">​</a></h4><p>現在我們需要為網絡共享文件創建一個系統用户。下面是非常簡單的步驟：</p><ul><li>在Systems Settings下點擊<strong>User Accounts</strong>。</li><li>點擊<strong>unlock</strong>使其可用，以及+（<strong>加號</strong>）圖標。</li><li>點擊+（加號）圖標，創建一個新的系統用户。</li></ul><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/create-system-user1.jpg" alt=""></p><p>如上圖所示，需要輸入‘Full name’。當你輸入‘Full name’時，Username會自動填充為Full name。因為創建這個用户是為了共享文件，所以還要指定Account Type為‘<strong>Standard</strong>’。</p><p>完成上述步驟，點擊添加，你就創建好一個系統用户。這個用户還沒有被激活，所以需要為其設置密碼來激活。確保Users accounts界面已經解鎖。點擊尚不可用的賬户，輸入一個新密碼，然後確認密碼，點擊Change。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/activate-system-user.jpg" alt=""></p><p>耶！到目前為止我們已經安裝並配置好Samba，已經創建了一個系統用户以通過這個賬户在網絡上共享文件，而且也已經激活了新用户。現在來到配置Samba的最後一步，然後就可以共享文件夾了。</p><h4 id="添加samba新用户" tabindex="-1">添加Samba新用户 <a class="header-anchor" href="#添加samba新用户" aria-label="Permalink to “添加Samba新用户”">​</a></h4><p>打開Samba，在Preference先點擊Samba Users。填寫彈出的對話框，下面是其中幾個字段的説明：</p><p><strong>Unix Username</strong> - 在這種情況下，我選擇剛才創建的用户。</p><p><strong>Windows Username</strong> - 輸入你要訪問的Windows電腦的用户名。</p><p><strong>Samba Password</strong> - 輸入你要訪問的Windows電腦的密碼。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/samba-user-setting.jpg" alt=""></p><p>完成後點擊OK。現在做個深呼吸。你已經在Samba的幫助下成功創建一個網絡。然後重啓網絡或Samba服務，準備好和其它電腦共享文件。</p><pre><code>sudo restart smbd &amp;&amp; sudo restart nmbd
</code></pre><h4 id="通過網絡共享文件夾或文件" tabindex="-1">通過網絡共享文件夾或文件 <a class="header-anchor" href="#通過網絡共享文件夾或文件" aria-label="Permalink to “通過網絡共享文件夾或文件”">​</a></h4><p>在圖形用户界面下通過Samba共享文件是很簡單的。點擊加號圖標，會看到如圖所示的對話框：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/share-files-and-folders.jpg" alt=""></p><p>填寫完這些字段。在‘Directory’中，瀏覽要共享的文件夾。你會看到的字段的含義如下：</p><ul><li><strong>Share name</strong> 是其它人會看到的文件夾名字。</li><li><strong>Description</strong> 是要共享內容的簡單描述。</li><li><strong>Writeable</strong> 默認情況下共享的文件夾是‘read only’。如果允許網絡上的其他用户修改它們，設置為writable。</li><li><strong>Visiable</strong> 當你點擊Visiable時，就像它的名字一樣，共享文件夾就對網絡上的其他人可見。</li></ul><p>現在你可以設置共享文件夾的權限。點擊‘Access’選項，選擇想要共享文件夾的用户。當你選擇對所有人允許訪問後，這個文件夾就對網絡上的所有人可見。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/Screenshot-from-2015-02-28-202031.png" alt=""></p><p>最後點擊OK，完成共享。現在這個文件夾就與你想要共享的用户實現共享。你已經完成了網絡共享文件。還有其它要做的嗎？對！還不知道如何從網絡上移除文件夾？</p><h4 id="移除共享文件夾" tabindex="-1">移除共享文件夾 <a class="header-anchor" href="#移除共享文件夾" aria-label="Permalink to “移除共享文件夾”">​</a></h4><p>在網絡共享一段時間後，我們也需要移除其中的一些文件夾。操作很簡答，下面就是我們要做的。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/remove-shared-folder-from-network.jpg" alt=""></p><p>全部搞定！我們也可以使用終端進行網絡文件共享，但這樣沒有本文介紹的方法這麼容易。如果你確實想知道命令列操作，我會再寫一篇關於在Linux上使用命令列實現網絡文件共享的文章。</p><p>所以，你是怎麼找到這篇教程的呢？我希望看了這篇教程你可以<strong>很容易地在Ubuntu和Windows之間共享文件</strong>。如果你有任何問題或建議，請在評論裏説出來。</p><hr>`,49)),o("p",null,[t[4]||(t[4]=a("via: ",-1)),e(s,{href:"http://itsfoss.com/share-folders-local-network-ubuntu-windows/"},{default:n(()=>[...t[3]||(t[3]=[a("http://itsfoss.com/share-folders-local-network-ubuntu-windows/",-1)])]),_:1})]),o("p",null,[t[8]||(t[8]=a("作者：",-1)),e(s,{href:"http://itsfoss.com/author/sohail/"},{default:n(()=>[...t[5]||(t[5]=[a("Mohd Sohail",-1)])]),_:1}),t[9]||(t[9]=a(" 譯者：",-1)),e(s,{href:"https://github.com/KayGuoWhu"},{default:n(()=>[...t[6]||(t[6]=[a("KayGuoWhu",-1)])]),_:1}),t[10]||(t[10]=a(" 校對：",-1)),e(s,{href:"https://github.com/wxy"},{default:n(()=>[...t[7]||(t[7]=[a("wxy",-1)])]),_:1})]),o("p",null,[t[13]||(t[13]=a("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[11]||(t[11]=[a("LCTT",-1)])]),_:1}),t[14]||(t[14]=a(" 原創翻譯，",-1)),e(s,{href:"http://linux.cn/"},{default:n(()=>[...t[12]||(t[12]=[a("Linux中國",-1)])]),_:1}),t[15]||(t[15]=a(" 榮譽推出",-1))])])}const _=i(u,[["render",m]]);export{U as __pageData,_ as default};
